import test from 'node:test';
import assert from 'node:assert/strict';
import { parseEnv } from '/workspace/src/index.mjs';

test('parseEnv parses literal env lines, duplicate keys, empty values, and __proto__', () => {
  const result = parseEnv(`
    # comment
    KEY = value=with=equals # inline hash
    KEY=last
    INLINE=value # remains literal
    EMPTY=
    __proto__=safe
    REF=${'${OTHER}'}
  `);

  assert.equal(Object.getPrototypeOf(result), Object.prototype);
  assert.equal(Object.prototype.hasOwnProperty.call(result, '__proto__'), true);
  assert.equal(result.KEY, 'last');
  assert.equal(result.INLINE, 'value # remains literal');
  assert.equal(result.EMPTY, '');
  assert.equal(result.__proto__, 'safe');
  assert.equal(result.REF, '${OTHER}');
  assert.deepEqual(Object.keys(result), ['KEY', 'INLINE', 'EMPTY', '__proto__', 'REF']);
});

test('parseEnv rejects malformed lines with ENV_SYNTAX', () => {
  assert.throws(
    () => parseEnv('not a key=value line'),
    (error) => error.code === 'ENV_SYNTAX',
  );
});

