import test from 'node:test';
import assert from 'node:assert/strict';
import { resolveEnv } from '/workspace/src/index.mjs';

test('resolveEnv recursively expands forward references and returns a copy', () => {
  const input = { MESSAGE: '${GREETING}, ${NAME}!', NAME: 'Ada', GREETING: 'Hello' };
  const result = resolveEnv(input);

  assert.deepEqual(result, { MESSAGE: 'Hello, Ada!', NAME: 'Ada', GREETING: 'Hello' });
  assert.notStrictEqual(result, input);
  assert.equal(Object.getPrototypeOf(result), Object.prototype);
  assert.deepEqual(input, { MESSAGE: '${GREETING}, ${NAME}!', NAME: 'Ada', GREETING: 'Hello' });
});

